/**
 * Goodness-of-fit of every sampler against scipy reference data
 * (generated by scripts/make_reference.py into test/fixtures/reference.json).
 */
import { describe, test, expect } from 'vitest'
import { readFileSync } from 'node:fs'
import * as lib from '../index.js'
import { expectChiSquare } from './helpers/stats.js'

const decode = (a) => (a === 'Infinity' ? Infinity : a === '-Infinity' ? -Infinity : a)
const cases = JSON.parse(readFileSync(new URL('./fixtures/reference.json', import.meta.url), 'utf8'))
  .map((c) => ({ ...c, args: c.args.map(decode) }))
const N = 20000

function expectVentiles(xs, quantiles) {
  const counts = new Array(quantiles.length + 1).fill(0)
  for (const x of xs) {
    let lo = 0
    let hi = quantiles.length
    while (lo < hi) {
      const mid = (lo + hi) >> 1
      if (x <= quantiles[mid]) hi = mid
      else lo = mid + 1
    }
    counts[lo]++
  }
  const expected = xs.length / counts.length
  const stat = counts.reduce((s, c) => s + (c - expected) ** 2 / expected, 0)
  // chi-square with 19 degrees of freedom, p = 0.001
  expect(stat).toBeLessThan(43.82)
}

describe('goodness of fit against scipy', () => {
  cases.forEach((c, index) => {
    test(`${c.fn}(${c.args.map((a) => JSON.stringify(a)).join(', ')})`, () => {
      expect(typeof lib[c.fn]).toBe('function')
      lib.seed(1000 + index)
      const xs = lib[c.fn](...c.args, N)
      expect(xs).toHaveLength(N)
      if (c.type === 'continuous') {
        expectVentiles(xs, c.quantiles)
      } else {
        const pmf = (k) => (k >= c.lo && k < c.lo + c.pmf.length ? c.pmf[k - c.lo] : 0)
        expectChiSquare(xs, pmf, c.lo, c.lo + c.pmf.length - 1)
      }
    })
  })
})
